<template><div class="messages"><aside class="tenant-card conversations"><h3>站内沟通</h3><div v-for="item in conversations" :key="item.id" class="conv" :class="{active:item.id===activeId}" @click="select(item.id)"><strong>{{ item.property_title || item.subject }}</strong><p>{{ item.last_message || '暂无消息' }}</p></div><div v-if="!conversations.length" class="empty-state">暂无沟通记录。</div></aside><section class="tenant-card chat"><template v-if="activeId"><div class="chat-list"><div v-for="msg in messages" :key="msg.id" class="msg" :class="msg.sender_role"><span>{{ msg.content }}</span><small>{{ msg.created_at }}</small></div></div><div class="send"><el-input v-model="content" placeholder="输入消息，所有沟通都会留存在系统内" @keyup.enter="send"/><el-button type="primary" @click="send">发送</el-button></div></template><div v-else class="empty-state">请选择一个会话。</div></section></div></template>
<script setup>import { onMounted, ref } from 'vue'; import { tenantApi } from '@/api/modules/tenant'; const conversations=ref([]),messages=ref([]),activeId=ref(null),content=ref(''); async function load(){conversations.value=(await tenantApi.getConversations()).data||[]} async function select(id){activeId.value=id;messages.value=(await tenantApi.getMessages(id)).data||[]} async function send(){if(!content.value.trim())return; await tenantApi.sendMessage(activeId.value,content.value); content.value=''; await select(activeId.value); await load()} onMounted(load)</script>
<style scoped>.messages{display:grid;grid-template-columns:320px 1fr;gap:14px}.conversations h3{font-size:16px;margin:0 0 12px}.conv{padding:12px;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:10px;cursor:pointer}.conv.active{border-color:#0f766e;background:#f0fdfa}.conv p{margin:4px 0 0;color:#64748b;font-size:13px}.chat{min-height:560px;display:flex;flex-direction:column}.chat-list{flex:1;display:flex;flex-direction:column;gap:10px;overflow:auto}.msg{max-width:72%;display:flex;flex-direction:column}.msg span{padding:10px 12px;border-radius:8px;background:#f1f5f9}.msg.tenant{align-self:flex-end}.msg.tenant span{background:#0f766e;color:#fff}.msg small{font-size:11px;color:#94a3b8;margin-top:3px}.send{display:flex;gap:10px;margin-top:12px}@media(max-width:900px){.messages{grid-template-columns:1fr}.chat{min-height:420px}}</style>
